import{_ as o,C as r,o as t,c as n,a2 as i,b as l,w as a,a as d,E as h,a3 as p}from"./chunks/framework.O93z6AWZ.js";const w=JSON.parse('{"title":"Working with Antigravity & AI Agents — Student Quick Guide","description":"","frontmatter":{"title":"Working with Antigravity & AI Agents — Student Quick Guide"},"headers":[],"relativePath":"en/ai_workflow.md","filePath":"en/ai_workflow.md"}'),c={name:"en/ai_workflow.md"};function g(u,e,k,m,b,y){const s=r("Mermaid");return t(),n("div",null,[e[1]||(e[1]=i('<h1 id="🤖-working-with-antigravity-ai-agents" tabindex="-1">🤖 Working with Antigravity &amp; AI Agents <a class="header-anchor" href="#🤖-working-with-antigravity-ai-agents" aria-label="Permalink to &quot;🤖 Working with Antigravity &amp; AI Agents&quot;">​</a></h1><blockquote><p>A 10-minute guide to running your course project with Google Antigravity and other AI agents (Claude, ChatGPT, …) and submitting it correctly. The rules that are graded live in the <a href="/hmyt-book/en/course_project">Management Framework &amp; Rubric</a> and <a href="/hmyt-book/en/submit">Submit Assignment</a>. If anything here conflicts with them, they win.</p></blockquote><p>Tools are <strong>your team&#39;s choice</strong> — free or paid, any combination. What is fixed is the workflow below and the red lines in Section 5.</p><hr><h2 id="_1-the-setup-in-one-picture" tabindex="-1">1. The setup in one picture <a class="header-anchor" href="#_1-the-setup-in-one-picture" aria-label="Permalink to &quot;1. The setup in one picture&quot;">​</a></h2>',5)),(t(),l(p,null,{default:a(()=>[h(s,{id:"mermaid-15",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%22Team%20fork%20of%3Cbr%2F%3Ehmyt-project%22%5D%20--%3E%7Cclone%7C%20B%5B%22Antigravity%3Cbr%2F%3E(your%20laptop)%22%5D%0A%20%20B%20--%3E%7C%22agent%20writes%20code%2C%3Cbr%2F%3Eyou%20review%20diff%22%7C%20C%5B%22Milestone%20branch%3Cbr%2F%3Egd1%20%E2%80%A6%20gd7%22%5D%0A%20%20D%5B%22Second%20AI%20agent%3Cbr%2F%3E(Claude%20%2F%20ChatGPT%20%2F%20%E2%80%A6)%22%5D%20--%3E%7C%22cross-review%22%7C%20C%0A%20%20C%20--%3E%7Cpush%7C%20A%0A%20%20A%20--%3E%7C%22Pull%20Request%3Cbr%2F%3Esubmit%2F%26lt%3Bslug%26gt%3B-%26lt%3Bteam%26gt%3B%22%7C%20E%5B%22fossbk-spec%2Fhmyt-project%3Cbr%2F%3ECI%20%E2%9C%85%20%2B%20instructor%20review%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=i(`<table tabindex="0"><thead><tr><th>Tool</th><th>Good for</th><th>Never use it for</th></tr></thead><tbody><tr><td><strong>Antigravity</strong> (agent in an IDE, app or <code>agy</code> CLI)</td><td>Writing and running code, fixing errors, refactoring, plans you can review before execution</td><td>Deciding the study design or the metrics on your behalf</td></tr><tr><td><strong>A second agent</strong> (Claude, ChatGPT, Codex, Gemini …)</td><td>Reviewing the first agent&#39;s code, explaining concepts, polishing English</td><td>Producing citations or numbers you have not checked</td></tr><tr><td><strong>PubMed / Google Scholar / Crossref</strong></td><td>Finding and <strong>verifying</strong> every reference</td><td>—</td></tr></tbody></table><h2 id="_2-day-1-—-set-up-one-repository-for-the-whole-project" tabindex="-1">2. Day 1 — set up one repository for the whole project <a class="header-anchor" href="#_2-day-1-—-set-up-one-repository-for-the-whole-project" aria-label="Permalink to &quot;2. Day 1 — set up one repository for the whole project&quot;">​</a></h2><ol><li><strong>One member forks</strong> <a href="https://github.com/fossbk-spec/hmyt-project" target="_blank" rel="noreferrer"><code>hmyt-project</code></a> and adds the other members as collaborators. The whole team works in this fork; there is no separate project repository and nothing to copy at the end.</li><li>Create your team folder from the template (see <a href="/hmyt-book/en/submit">Submit</a>, steps 2–3): <code>submissions/&lt;topic_slug&gt;_&lt;team_code&gt;/</code>. <strong>All your work lives inside this folder</strong>: CI rejects a PR that touches anything else.</li><li>Clone the fork and open it in Antigravity.</li><li>Add a short <code>AGENTS.md</code> <strong>inside your team folder</strong>. Antigravity, Codex and most other agents read it automatically; for Claude Code, add a <code>CLAUDE.md</code> with the line <code>@AGENTS.md</code>.</li></ol><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># AGENTS.md — &lt;</span><span style="--shiki-light:#22863A;--shiki-light-font-weight:bold;--shiki-dark:#85E89D;--shiki-dark-font-weight:bold;">topic_slug</span><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">&gt;_&lt;</span><span style="--shiki-light:#22863A;--shiki-light-font-weight:bold;--shiki-dark:#85E89D;--shiki-dark-font-weight:bold;">team_code</span><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Topic: &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">topic</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> name</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> +</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> link</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> to</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> the</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> topic</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> page</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;. Dataset: &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">public</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> dataset</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> +</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> URL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Work only inside submissions/&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">topic_slug</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;_&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">team_code</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;/.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Rules:</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Never read, upload or print real patient data; no API keys or .env files.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Split by patient BEFORE any scaling/imputation; fit preprocessing on train only.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Never invent references, numbers or results. Every number in report/ must come</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  from code in src/. Mark anything unverified as [TODO: verify].</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Python 3.11, scikit-learn/PyTorch; fix random seeds; log runs.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Before finishing a task: run the code, show the diff, list what you did not test.</span></span></code></pre></div><h2 id="_3-daily-loop-one-milestone-one-branch-one-task-one-request" tabindex="-1">3. Daily loop: one milestone = one branch, one task = one request <a class="header-anchor" href="#_3-daily-loop-one-milestone-one-branch-one-task-one-request" aria-label="Permalink to &quot;3. Daily loop: one milestone = one branch, one task = one request&quot;">​</a></h2><p><strong>The whole submission flow, in one line:</strong> one fork → one milestone branch per deadline, pushed to the fork → <strong>one Pull Request at the very end</strong>.</p><table tabindex="0"><thead><tr><th>When</th><th>What you do on GitHub</th></tr></thead><tbody><tr><td>Each milestone (weeks 3, 6, 10, 12)</td><td>Start the branch named in the rubric (<code>gd1-proposal</code>, <code>gd2-dataset-eda</code>, … <code>gd6-evaluation-xai</code>) from the previous one, <strong>push it to your fork before the deadline</strong>. The instructor reviews that branch in your fork. No Pull Request yet.</td></tr><tr><td>Final (week 15)</td><td>Finish <code>gd7-ieee-paper</code>, then open <strong>the only Pull Request</strong> (Section 7).</td></tr></tbody></table><p>Do not open a Pull Request per milestone: once merged, your folder is locked and cannot be changed through a normal PR.</p><p>For each task:</p><table tabindex="0"><thead><tr><th>Step</th><th>You</th><th>Agent</th></tr></thead><tbody><tr><td><strong>Plan</strong></td><td>Describe one small task (e.g. &quot;patient-level split for PTB-XL&quot;)</td><td>Proposes an implementation plan</td></tr><tr><td><strong>Review the plan</strong></td><td>Approve, correct or reject it <em>before</em> any code is written</td><td>—</td></tr><tr><td><strong>Build</strong></td><td>—</td><td>Writes code, runs it, reports results</td></tr><tr><td><strong>Check</strong></td><td>Read the diff, re-run the code yourself, look at the outputs</td><td>—</td></tr><tr><td><strong>Commit</strong></td><td>Commit <strong>from your own GitHub account</strong> with a clear message</td><td>—</td></tr></tbody></table><p>Rules of thumb:</p><ul><li>Keep tasks small. One notebook or one function per request is easy to review.</li><li>Use Antigravity&#39;s <strong>worktree mode</strong> or a separate branch for experiments, so a bad run never breaks your milestone branch.</li><li><strong>Every member commits.</strong> The rubric gives 0 to a member with no commits (&quot;freerider&quot; rule), and agent commits made from one laptop count only for that person.</li></ul><h2 id="_4-two-agent-pattern-one-writes-another-reviews" tabindex="-1">4. Two-agent pattern: one writes, another reviews <a class="header-anchor" href="#_4-two-agent-pattern-one-writes-another-reviews" aria-label="Permalink to &quot;4. Two-agent pattern: one writes, another reviews&quot;">​</a></h2><p>The most expensive mistakes in this course (data leakage: −50% of the milestone) are easy for a <em>second</em> agent to spot. Paste the diff or file into another agent with a prompt like:</p><ul><li><em>&quot;Review this code for train/test leakage: same patient in both sets, scaling or imputation fitted before the split, test data used for model selection. Cite line numbers.&quot;</em></li><li><em>&quot;Check that every metric in this table is produced by this code. List any number you cannot trace.&quot;</em></li><li><em>&quot;I am a student. Explain what this function does and what could go wrong, without rewriting it.&quot;</em></li></ul><p>Treat the review as advice: you decide, and you must be able to explain the code at the defense.</p><h2 id="_5-red-lines-graded-see-rubric-part-iv" tabindex="-1">5. Red lines (graded, see Rubric Part IV) <a class="header-anchor" href="#_5-red-lines-graded-see-rubric-part-iv" aria-label="Permalink to &quot;5. Red lines (graded, see Rubric Part IV)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Never</th><th>Penalty</th></tr></thead><tbody><tr><td>Put real, non-de-identified patient data in a prompt or in the repository</td><td>−30 points on the final grade, project suspended</td></tr><tr><td>Commit API keys, tokens, passwords or <code>.env</code> files</td><td>CI blocks the PR</td></tr><tr><td>Use a reference you have not opened yourself. AI tools regularly invent papers, and a fabricated DOI often points to a real but unrelated paper. Check title, authors and year on <a href="https://search.crossref.org" target="_blank" rel="noreferrer">Crossref</a> or PubMed</td><td>Project voided (Zero-Hallucination policy)</td></tr><tr><td>Report a number that your code did not produce</td><td>Project voided</td></tr><tr><td>Let the agent decide the split, the metrics or the clinical interpretation without checking them</td><td>Leakage −50%; you cannot defend it in Q&amp;A</td></tr></tbody></table><h2 id="_6-ai-disclosure-log-as-you-go" tabindex="-1">6. AI disclosure: log as you go <a class="header-anchor" href="#_6-ai-disclosure-log-as-you-go" aria-label="Permalink to &quot;6. AI disclosure: log as you go&quot;">​</a></h2><p>Keep <code>docs/ai_disclosure_log.md</code> inside your team folder from day 1. Add one line whenever an AI tool shaped code, text or a decision:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| Date | Member (student ID) | Tool | Task | What we checked / changed |</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">|---|---|---|---|---|</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| 2026-10-27 | 2021xxxx | Antigravity | Patient-level split | Re-ran, verified no patient overlap |</span></span></code></pre></div><p>Your IEEE paper must end with an <strong>&quot;AI and AI-Assisted Technologies Disclosure&quot;</strong> section (tools, purpose, and a statement that the team takes full responsibility). Write it from this log. Full policy: <a href="/hmyt-book/du_an_mon_hoc#phan-vii-chinh-sach-su-dung-ai-minh-bach-ai-disclosure-policy">Vietnamese rubric, Part VII</a>.</p><h2 id="_7-submitting" tabindex="-1">7. Submitting <a class="header-anchor" href="#_7-submitting" aria-label="Permalink to &quot;7. Submitting&quot;">​</a></h2><p>When <code>gd7-ieee-paper</code> is final, create <code>submit/&lt;topic_slug&gt;-&lt;team_code&gt;</code> from it (<code>git switch -c submit/&lt;topic_slug&gt;-&lt;team_code&gt; gd7-ieee-paper</code>), push it, open the Pull Request, and follow the <a href="/hmyt-book/en/submit">Submit checklist</a>:</p><ul><li>[ ] <code>python scripts/validate_submission.py submissions/&lt;topic_slug&gt;_&lt;team_code&gt;</code> shows <code>[PASSED]</code></li><li>[ ] <code>python scripts/review_project.py submissions/&lt;topic_slug&gt;_&lt;team_code&gt;</code>: ❌/⚠️ items read and handled</li><li>[ ] No real patient data, no keys, student IDs instead of names, large data linked rather than committed</li><li>[ ] <code>ai_disclosure_log.md</code> and the paper&#39;s disclosure section are complete</li><li>[ ] Every reference was checked by a human</li><li>[ ] PR opened to <code>main</code> of <code>fossbk-spec/hmyt-project</code>, CI ✅</li></ul><p>An agent may run these scripts and fix what they report, but a team member reads every fix before pushing.</p><hr><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ol><li>Google. <em>Antigravity documentation: Getting started; Rules; Plans.</em> <a href="https://antigravity.google/docs/getting-started" target="_blank" rel="noreferrer">https://antigravity.google/docs/getting-started</a> (accessed 27 Oct 2026).</li><li>AGENTS.md: an open format for guiding coding agents. <a href="https://agents.md" target="_blank" rel="noreferrer">https://agents.md</a>.</li><li>Anthropic. <em>Claude Code overview.</em> <a href="https://code.claude.com/docs/en/overview" target="_blank" rel="noreferrer">https://code.claude.com/docs/en/overview</a>.</li><li>OpenAI. <em>Codex.</em> <a href="https://developers.openai.com/codex" target="_blank" rel="noreferrer">https://developers.openai.com/codex</a>.</li><li>GitHub Docs. <em>Fork a repository.</em> <a href="https://docs.github.com/en/pull-requests/collaborating-with-pull-requests/working-with-forks/fork-a-repo" target="_blank" rel="noreferrer">https://docs.github.com/en/pull-requests/collaborating-with-pull-requests/working-with-forks/fork-a-repo</a>.</li><li>ICMJE. <em>Recommendations</em>, section on AI-assisted technology. <a href="https://www.icmje.org/recommendations/" target="_blank" rel="noreferrer">https://www.icmje.org/recommendations/</a>.</li><li>Crossref. <em>Search metadata.</em> <a href="https://search.crossref.org" target="_blank" rel="noreferrer">https://search.crossref.org</a>.</li></ol>`,29))])}const E=o(c,[["render",g]]);export{w as __pageData,E as default};
